/* Complete interactive design prototype. All records are fictional and session-only. */
const roles={reader:'Bạn đọc',circulation:'Cán bộ mượn trả',catalog:'Cán bộ biên mục',warehouse:'Cán bộ kho',digital:'Cán bộ học liệu số',manager:'ManagerLib · Quản lý thư viện',admin:'Admin · Quản trị hệ thống'};
const menus={reader:[['home','Trang chủ'],['search','Tra cứu'],['loans','Mượn & đặt trước'],['fees','Khoản phạt'],['requests','Yêu cầu của tôi'],['submit','Nộp công trình'],['mydocs','Hồ sơ đã nộp'],['profile','Hồ sơ & thẻ']],circulation:[['work','Công việc hôm nay'],['desk','Quầy mượn trả'],['patrons','Bạn đọc & thẻ'],['transactions','Khoản mượn & hàng chờ'],['cases','Sự cố & đề xuất'],['payments','Khoản phạt & thu tiền']],catalog:[['work','Công việc hôm nay'],['inventory','Danh mục tài liệu'],['editor','Biên tập bản ghi'],['ai','Hỗ trợ biên mục']],warehouse:[['work','Công việc hôm nay'],['copies','Bản sao & vị trí'],['stock','Kiểm kê'],['cases','Sự cố & đề xuất']],digital:[['work','Công việc hôm nay'],['queue','Tiếp nhận công trình'],['resources','Tài nguyên số'],['cases','Sự cố & đề xuất']],manager:[['work','Công việc hôm nay'],['approvals','Hàng chờ phê duyệt'],['reports','Báo cáo'],['policy','Chính sách mượn'],['audit','Nhật ký thao tác']],admin:[['work','Công việc hôm nay'],['accounts','Tài khoản & vai trò'],['settings','Cấu hình hệ thống'],['audit','Nhật ký thao tác']]};
const session={role:null};
const db={fees:[{id:1,title:'Cấu trúc dữ liệu và giải thuật · giao dịch cũ',amount:25000,paid:0,waived:0,status:'Chưa thu'}],requests:[{id:1,title:'Bổ sung giáo trình an toàn thông tin',type:'Đề xuất bổ sung',status:'Đang xem xét',detail:'Đề xuất tài liệu phục vụ học phần mới.'}],cases:[{id:1,title:'Tem barcode bị mờ · HT-004-001',type:'Sự cố vật lý',status:'Mới tiếp nhận',detail:'Tem bị mờ, vẫn xác định được mã cuốn.'}],approvals:[],accounts:[{id:1,name:'Nguyễn Minh Anh',email:'minhanh@example.edu',role:'reader',status:'Hoạt động'},{id:2,name:'Trần Thủ Thư',email:'thuthu@example.edu',role:'circulation',status:'Hoạt động'},{id:3,name:'Lê Biên Mục',email:'bienmuc@example.edu',role:'catalog',status:'Hoạt động'}],copies:[{id:1,code:'AI-001-001',book:1,location:'T2 · A03 · K05',status:'Sẵn sàng'},{id:2,code:'HT-004-001',book:4,location:'T2 · A03 · K02',status:'Đang mượn'},{id:3,code:'TD-006-001',book:6,location:'T3 · B01 · K04',status:'Sẵn sàng'}],stocks:[{id:1,title:'Kiểm kê tầng 2 · tháng 10',area:'Tầng 2',status:'Đang thực hiện',seen:[]}],resources:[{id:1,title:'Thiết kế trải nghiệm người dùng',kind:'Tệp PDF',access:'Thành viên trường',status:'Đã công bố',version:1},{id:2,title:'Cổng tạp chí khoa học mở',kind:'Liên kết ngoài',access:'Công khai',status:'Chưa công bố',version:1,url:'https://doaj.org'}],policies:[{id:1,name:'Sinh viên · Sách tham khảo',limit:5,days:30,renew:1,extra:7,fee:5000,effective:'2026-09-01',status:'Đang áp dụng'}],audit:[],receipts:[],card:{status:'Hoạt động',expiry:'2027-06-30',phone:'0900000000',email:'minhanh@example.edu'},settings:{branch:'Cơ sở A',hold:5,email:'library@example.edu',closed:'Chủ nhật'},editId:null,stockId:1};
books.forEach(b=>b.status='Đã công bố');
state.submissions.push({id:1,title:'Ứng dụng học máy trong phân loại tài liệu',advisor:'TS. Nguyễn Văn An',type:'Luận văn thạc sĩ',year:2026,abstract:'Khảo sát mô hình phân loại tài liệu phục vụ tra cứu.',access:'Thành viên trường',filename:'luan-van-mau.pdf',status:'Chờ kiểm tra'});
const css=document.createElement('style');css.textContent=`.header nav{overflow:auto;gap:20px}.header nav button{white-space:nowrap}.header{gap:22px}.loginlayout{min-height:72vh;display:grid;grid-template-columns:1fr 1fr;background:white}.loginart{background:#183c5a;color:white;padding:65px;position:relative}.loginart h1{font-size:48px;max-width:450px}.loginart .muted{color:#c1d4e1}.loginart .shelves{margin-top:65px;display:flex;gap:9px;align-items:flex-end;border-bottom:9px solid #6a8ba3}.shelves i{height:140px;width:45px;background:#3f7581;border-radius:4px 4px 0 0}.shelves i:nth-child(2n){height:185px;background:#9d8161}.shelves i:nth-child(3n){height:165px;background:#6784a3}.loginform{padding:50px;max-width:650px}.rolegrid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:20px 0}.rolegrid button{font-size:12px;text-align:left}.rolegrid button.selected{background:var(--pale);border-color:var(--blue);color:var(--blue)}.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:24px 0}.tile{background:white;border:1px solid var(--line);border-radius:10px;padding:22px}.tile strong{display:block;font:32px Georgia;margin:10px 0}.tile p{font-size:13px;color:var(--muted)}.split{display:grid;grid-template-columns:1.5fr 1fr;gap:22px}.toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:18px 0}.toolbar input,.toolbar select{padding:10px;border:1px solid var(--line);border-radius:6px;background:white;max-width:100%}.toolbar input{min-width:200px}.error{color:#a52b32;font-size:13px;margin:12px 0}.detailtext{white-space:pre-wrap;line-height:1.7;color:var(--muted)}.statbar{display:flex;align-items:center;gap:12px;margin:13px 0}.statbar span{width:120px;font-size:13px}.statbar i{height:15px;background:#487bb9;border-radius:3px;display:block}.staffnav{position:sticky;top:0;align-self:start;min-height:70vh}.staffnav button{line-height:1.4}.staffnav .note{font-size:11px}.panel+.panel{margin-top:20px}.dialogform{display:grid;gap:14px}dialog{max-height:88vh;overflow:auto}.demohead{font-size:12px;margin:12px 0;color:var(--muted)}.detailaction{display:flex;gap:8px;flex-wrap:wrap}.alertbox{background:#fff4dc;color:#805e1b;padding:14px;border-radius:7px;font-size:13px;margin:16px 0}.header .brand small{letter-spacing:1.3px}.route-count{font-size:11px;color:var(--muted)}@media(max-width:1000px){.tiles{grid-template-columns:repeat(2,1fr)}.loginart{padding:40px}.split{grid-template-columns:1fr}}@media(max-width:760px){.loginlayout{grid-template-columns:1fr}.loginart{padding:30px}.loginart h1{font-size:32px}.loginart .shelves{display:none}.loginform{padding:24px}.tiles{grid-template-columns:1fr}.staffnav{position:static;min-height:0}.toolbar{flex-wrap:wrap}.toolbar input{width:100%}.header .profile span{display:none}.staffnav .note{display:none}.rolegrid{grid-template-columns:1fr 1fr}}`;document.head.appendChild(css);
const old={search,detail,loans,submit,desk,inventory,reader,saveForm,nextStep,commitDesk};
function money(v){return Number(v).toLocaleString('vi-VN')+' đ'}
function log(action){db.audit.unshift({time:new Date().toLocaleString('vi-VN'),role:roles[session.role]||'Khách',action})}
function btn(label,action,primary=false){return `<button class="${primary?'primary':'small'}" onclick="${action}">${label}</button>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="muted">Chưa có dữ liệu phù hợp.</td></tr>`}</tbody></table></div>`}
function inputField(name,label,value='',type='text',options=null){return `<label class="field">${label}${options?`<select name="${name}">${options.map(x=>`<option value="${esc(x)}" ${String(value)===String(x)?'selected':''}>${esc(x)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}" required>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''} required>`}</label>`}
function formDialog(title,fields,action,ok='Lưu thay đổi',note=''){let d=$('#dialog');d.innerHTML=`<h2>${esc(title)}</h2>${note?`<p class="muted">${esc(note)}</p>`:''}<form class="dialogform" id="dynamicform">${fields}<div class="error" id="formerror" role="alert"></div><div class="actions"><button type="button" onclick="$('#dialog').close()">Hủy</button><button class="primary">${ok}</button></div></form>`;$('#dynamicform').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));try{action(data);d.close();render()}catch(error){$('#formerror').textContent=error.message}};d.showModal()}
function change(item,key,value,msg){item[key]=value;log(msg);render();toast(msg)}
function amountLeft(f){return Math.max(0,f.amount-f.paid-f.waived)}
function addApproval(kind,title,data){if(db.approvals.some(a=>a.kind===kind&&a.data===data&&a.status==='Chờ duyệt'))return toast('Hồ sơ này đã có trong hàng chờ.');db.approvals.push({id:db.approvals.length+1,kind,title,data,status:'Chờ duyệt'});log('Trình duyệt: '+title);toast('Đã chuyển hồ sơ đến ManagerLib.')}
function permitted(p){if(session.pendingAccount)return p==='password'||p==='login';if(['login','home','search','detail','reader','help'].includes(p))return true;if(!session.role)return false;return (menus[session.role]||[]).some(x=>x[0]===p)||p==='notifications'||p==='password'||(session.role==='reader'&&p==='profile')||(session.role==='catalog'&&p==='editor')}
go=function(p){if(!permitted(p)){toast('Đăng nhập bằng vai trò có quyền để mở chức năng này.');p='login'}state.page=p;state.staff=!!session.role&&session.role!=='reader'&&!['home','search','detail','reader','login'].includes(p);render();window.scrollTo(0,0)};
nav=function(){let list=session.role==='reader'?menus.reader.filter(x=>['home','search','loans','submit'].includes(x[0])):session.role?[['work','Bàn làm việc'],['search','Tra cứu tài liệu']]:[['home','Trang chủ'],['search','Tra cứu tài liệu']];$('#nav').innerHTML=list.map(([p,t])=>`<button class="${state.page===p?'active':''}" onclick="go('${p}')">${t}</button>`).join('');$('.profile').innerHTML=session.role?`<button class="small" onclick="go('notifications')" aria-label="Mở thông báo">Thông báo</button><div class="avatar">${session.role==='reader'?'MA':'CB'}</div><span>${session.role==='reader'?'Minh Anh':roles[session.role]}<small>Phiên thử giao diện</small></span>`:btn('Đăng nhập',"go('login')");$('#mode').textContent=session.role?'Đổi vai trò / Đăng xuất':'Xem các vai trò';$('#mode').onclick=()=>{session.role=null;go('login')};};
staffShell=function(title,sub,body){return shell(title,sub,body)};
function shell(title,sub,body){let menu=menus[session.role]||menus.reader;return `<div class="stafflayout"><aside class="staffnav"><small>${session.role==='reader'?'KHÔNG GIAN CỦA TÔI':'BÀN LÀM VIỆC'}</small>${menu.map(([p,t])=>`<button class="${state.page===p?'active':''}" onclick="go('${p}')">${t}</button>`).join('')}<div class="note">${roles[session.role]||'Khách'}<br>Quyền được mô phỏng ở frontend.</div></aside><section class="staffmain">${heading(session.role==='reader'?'Dịch vụ bạn đọc':'Nghiệp vụ thư viện',title,sub)}${body}</section></div>`}
const views={home:homeView,login:loginView,search:old.search,detail:old.detail,reader:old.reader,loans:()=>shell('Mượn và đặt trước','',old.loans()),submit:()=>shell('Nộp công trình','',old.submit()),desk:old.desk,inventory:catalogView,work:workView,fees:feesView,requests:requestsView,mydocs:mydocsView,profile:profileView,patrons:patronsView,transactions:transactionsView,cases:casesView,payments:paymentsView,editor:editorView,ai:aiView,copies:copiesView,stock:stockView,queue:intakeView,resources:resourcesView,approvals:approvalsView,reports:reportsView,policy:policyView,accounts:accountsView,settings:settingsView,audit:auditView,notifications:notificationsView};
render=function(){nav();$('#app').innerHTML=(views[state.page]||homeView)();if(state.page==='search')results();if(['loans','submit'].includes(state.page)){let nested=$('.staffmain .wrap');if(nested)nested.style.padding='0';}if(state.page==='login')window.loginRole='reader'};
function loginView(){return `<div class="loginlayout"><section class="loginart"><div class="eyebrow" style="color:#a8cddb">THƯ VIỆN ĐẠI HỌC</div><h1>Một tài khoản.<br>Cả không gian tri thức.</h1><p class="muted">Tìm tài liệu, theo dõi khoản mượn và gửi công trình. Cán bộ truy cập bàn làm việc theo vai trò được cấp.</p><div class="shelves" aria-hidden="true">${'<i></i>'.repeat(7)}</div></section><section class="loginform"><h2>Chọn vai trò để trải nghiệm</h2><p class="muted">Đây là đăng nhập mô phỏng. Không nhập mật khẩu tài khoản thật.</p><div class="rolegrid">${Object.entries(roles).map(([k,v])=>`<button id="role-${k}" class="${k==='reader'?'selected':''}" onclick="window.loginRole='${k}';document.querySelectorAll('.rolegrid button').forEach(b=>b.classList.remove('selected'));this.classList.add('selected')">${v}</button>`).join('')}</div><form onsubmit="event.preventDefault();loginDemo()">${inputField('scenario','Trạng thái thử nghiệm','Tài khoản hoạt động','text',['Tài khoản hoạt động','Tài khoản bị khóa','Xác thực thất bại'])}<div id="loginerror" class="error" role="alert"></div><button class="primary" style="width:100%;margin-top:16px">Vào giao diện vai trò đã chọn →</button></form><p class="demohead">Triển khai thật sẽ dùng đăng nhập tài khoản trường; quyền do máy chủ xác định.</p><button class="link" onclick="go('search')">Tiếp tục tra cứu với tư cách khách</button></section></div>`}
function loginDemo(){let scenario=document.querySelector('[name=scenario]').value;if(scenario!=='Tài khoản hoạt động'){$('#loginerror').textContent=scenario==='Tài khoản bị khóa'?'Tài khoản đang bị khóa. Liên hệ quản trị viên để được hỗ trợ.':'Chưa xác thực được tài khoản. Vui lòng thử lại.';return}session.role=window.loginRole||'reader';log('Bắt đầu phiên mẫu');go(session.role==='reader'?'home':'work')}
function homeView(){return `<div class="wrap"><div class="hero"><div>${heading('Khám phá · Học tập · Nghiên cứu','Tri thức bắt đầu từ một câu hỏi.','Tìm sách trên kệ, đọc học liệu số và kết nối với thư viện.')}</div><div class="hours"><span class="dot"></span>Không gian học tập<strong>Cơ sở A · 08:00–20:00</strong>Lịch minh họa</div></div><form class="searchbar" onsubmit="event.preventDefault();state.q=this.elements.keyword.value;go('search')"><input name="keyword" aria-label="Từ khóa tra cứu" placeholder="Bạn muốn tìm tài liệu gì?"><button class="primary">Tìm tài liệu</button></form><div class="tiles">${[['Tra cứu tài liệu','Sách, giáo trình, luận văn và nội dung toàn văn.','search'],['Thư viện của tôi','Theo dõi hạn trả và tình trạng đặt trước.','loans'],['Nộp công trình','Gửi hồ sơ và theo dõi quá trình tiếp nhận.','submit']].map(([t,s,p])=>`<section class="tile"><h2>${t}</h2><p>${s}</p>${btn('Khám phá →',`go('${p}')`)}</section>`).join('')}</div><section class="panel"><div class="row"><h2>Tài liệu nổi bật</h2>${btn('Xem tất cả',"go('search')")}</div><div class="tiles">${books.slice(0,3).map(b=>`<div><div class="bookstage">${cover(b)}</div><h3 style="margin-top:14px">${esc(b.title)}</h3><p class="muted">${esc(b.author)}</p>${btn('Xem tài liệu',`openBook(${b.id})`)}</div>`).join('')}</div></section></div>`}
function workView(){let list=(menus[session.role]||[]).filter(x=>x[0]!=='work');let pending=session.role==='manager'?db.approvals.filter(a=>a.status==='Chờ duyệt').length:state.submissions.filter(s=>s.status==='Chờ kiểm tra').length;return shell('Công việc hôm nay','Chọn nhiệm vụ để tiếp tục xử lý.',`<div class="tiles"><div class="tile"><span>Công việc chờ xem xét</span><strong>${pending}</strong><p>Trạng thái cập nhật theo thao tác trong phiên.</p></div><div class="tile"><span>Khoản mượn đang mở</span><strong>${state.loans.length}</strong><p>Dữ liệu giao dịch minh họa.</p></div><div class="tile"><span>Yêu cầu bạn đọc</span><strong>${db.requests.length}</strong><p>Gồm sự cố, đề xuất và hỗ trợ.</p></div></div><div class="tiles">${list.map(([p,t])=>`<section class="tile"><h3>${t}</h3><p>${roles[session.role]}</p>${btn('Mở công việc →',`go('${p}')`)}</section>`).join('')}</div>`)}
function feesView(){return shell('Khoản phạt của tôi','Xem nghĩa vụ tài chính và kết quả xử lý.',`<section class="panel">${table(['Nội dung','Phải nộp','Đã thu / miễn','Còn lại','Thao tác'],db.fees.map(f=>[esc(f.title),money(f.amount),money(f.paid)+' / '+money(f.waived),money(amountLeft(f)),btn('Đề nghị miễn giảm',`waiver(${f.id})`)]))}</section><div class="note">Bản mẫu ghi nhận thu tại quầy. Chưa tích hợp thanh toán trực tuyến.</div>`)}
function waiver(id){let f=db.fees.find(x=>x.id===id);formDialog('Đề nghị miễn giảm',inputField('reason','Lý do đề nghị','','textarea'),v=>{addApproval('Miễn giảm phạt',f.title,{fee:id,reason:v.reason});db.requests.push({id:db.requests.length+1,title:'Miễn giảm: '+f.title,type:'Miễn giảm',status:'Chờ duyệt',detail:v.reason})},'Gửi đề nghị')}
function requestsView(){return shell('Yêu cầu của tôi','Theo dõi sự cố tài liệu và đề xuất bổ sung.',`<div class="toolbar"><span>${db.requests.length} yêu cầu</span>${btn('Tạo yêu cầu',"newRequest()",true)}</div><section class="panel">${table(['Yêu cầu','Loại','Trạng thái',''],db.requests.map(r=>[esc(r.title),esc(r.type),badge(r.status,'blue'),btn('Xem / bổ sung',`requestDetail(${r.id})`)]))}</section>`)}
function newRequest(){formDialog('Gửi yêu cầu',inputField('type','Loại','Sự cố vật lý','text',['Sự cố vật lý','Lỗi tài liệu số','Đề xuất bổ sung'])+inputField('title','Tiêu đề')+inputField('detail','Mô tả','','textarea'),v=>{let r={id:db.requests.length+1,...v,status:'Mới tiếp nhận'};db.requests.push(r);db.cases.push({...r,id:db.cases.length+1,requestId:r.id});log('Gửi yêu cầu: '+r.title)},'Gửi yêu cầu')}
function requestDetail(id){let r=db.requests.find(x=>x.id===id);formDialog(esc(r.title),inputField('detail','Thông tin đã gửi / bổ sung',r.detail,'textarea'),v=>{r.detail=v.detail;let c=db.cases.find(x=>x.requestId===id);if(c)c.detail=v.detail;log('Bổ sung yêu cầu '+id)},'Gửi bổ sung',r.status)}
function profileView(){return shell('Hồ sơ và thẻ thư viện','Thông tin bạn đọc và điều kiện sử dụng dịch vụ.',`<div class="split"><section class="panel"><div class="borrower"><div class="avatar">MA</div><div><h2>Nguyễn Minh Anh</h2>SV20240018 · Công nghệ thông tin</div></div><p>Email: ${esc(db.card.email)}</p><p>Điện thoại: ${esc(db.card.phone)}</p>${btn('Cập nhật liên hệ','editContact()')}</section><section class="panel"><div class="eyebrow">THẺ THƯ VIỆN</div><h2>LIB-20240018</h2>${badge(db.card.status,db.card.status==='Hoạt động'?'':'warn')}<p style="margin-top:18px">Hạn thẻ: ${db.card.expiry}</p><p>Hạn mức mẫu: 5 cuốn · Gia hạn 1 lần</p></section></div>`)}
function editContact(){formDialog('Cập nhật liên hệ',inputField('email','Email',db.card.email,'email')+inputField('phone','Điện thoại',db.card.phone,'tel'),v=>{Object.assign(db.card,v);log('Cập nhật liên hệ bạn đọc')})}
function mydocsView(){return shell('Hồ sơ công trình của tôi','Tiếp nhận hồ sơ và công bố là các mốc riêng biệt.',`<div class="toolbar"><span>${state.submissions.length} hồ sơ</span>${btn('Nộp công trình mới',"go('submit')",true)}</div><section class="panel">${table(['Công trình','Trạng thái','Phản hồi',''],state.submissions.map(s=>[esc(s.title),badge(s.status,'blue'),esc(s.feedback||'Chưa có phản hồi'),btn('Xem / bổ sung',`supplement(${s.id})`)+(s.status==='Đã tiếp nhận'||s.status==='Đã công bố'?btn('Tải biên nhận',`receiptDoc(${s.id})`):'')]))}</section>`)}
function supplement(id){let s=state.submissions.find(x=>x.id===id);formDialog('Thông tin hồ sơ',inputField('abstract','Tóm tắt / thông tin bổ sung',s.abstract||'','textarea'),v=>{s.abstract=v.abstract;if(s.status==='Cần bổ sung')s.status='Chờ kiểm tra';log('Bổ sung hồ sơ '+id)},'Lưu bổ sung',s.title+' · '+s.status)}
function receiptDoc(id){let s=state.submissions.find(x=>x.id===id);downloadText('bien-nhan-'+id+'.txt','BIÊN NHẬN MINH HỌA\n'+s.title+'\nTrạng thái: '+s.status+'\nKhông có giá trị hành chính.')}
function patronsView(){return shell('Bạn đọc và thẻ','Tra cứu hồ sơ và quản lý hiệu lực thẻ.',`<section class="panel"><div class="toolbar"><input aria-label="Tìm bạn đọc" placeholder="Tên hoặc mã sinh viên" oninput="filterRows(this)"></div>${table(['Bạn đọc','Thẻ','Hiệu lực','Đang mượn','Thao tác'],[['<strong>Nguyễn Minh Anh</strong>SV20240018','LIB-20240018',badge(db.card.status,db.card.status==='Hoạt động'?'':'warn')+'<br>'+db.card.expiry,state.loans.length,btn('Gia hạn thẻ','cardRenew()')+' '+btn(db.card.status==='Hoạt động'?'Khóa thẻ':'Mở khóa thẻ','cardToggle()')]])}</section>`)}
function cardRenew(){formDialog('Gia hạn thẻ',inputField('expiry','Ngày hết hạn mới',db.card.expiry,'date'),v=>{if(v.expiry<=db.card.expiry)throw Error('Hạn mới phải sau hạn hiện tại.');db.card.expiry=v.expiry;log('Gia hạn thẻ đến '+v.expiry)})}
function cardToggle(){formDialog(db.card.status==='Hoạt động'?'Khóa thẻ':'Mở khóa thẻ',inputField('reason','Lý do'),v=>{db.card.status=db.card.status==='Hoạt động'?'Bị khóa':'Hoạt động';log(db.card.status+' thẻ: '+v.reason)})}
function transactionsView(){return shell('Khoản mượn và hàng chờ','Theo dõi từng giao dịch và yêu cầu đặt trước.',`<section class="panel"><h2>Khoản mượn đang mở</h2>${table(['Tài liệu','Bạn đọc','Hạn trả',''],state.loans.map(l=>[esc(book(l.id).title),'Minh Anh',l.due,l.renew?'Đã hết lượt gia hạn':btn('Gia hạn',`renew(${l.id})`)]))}</section><section class="panel"><h2>Đặt trước</h2>${table(['Tài liệu','Trạng thái','Điểm nhận',''],state.holds.map(h=>[esc(book(h.id).title),badge(h.status||'Chờ sách','blue'),'Cơ sở A',btn('Phân bổ bản sao',`allocateHold(${h.id})`)]))}</section>`)}
function allocateHold(id){let h=state.holds.find(x=>x.id===id);if(book(id).copies<1)return toast('Chưa có bản sao sẵn sàng để phân bổ.');if(h.status==='Chờ nhận')return toast('Yêu cầu đã được phân bổ.');h.status='Chờ nhận';book(id).copies--;log('Giữ bản sao cho yêu cầu '+id);render();toast('Đã giữ sách, thông báo được ghi nhận trong bản mẫu.')}
function relevantCases(){return db.cases.filter(c=>session.role==='digital'?c.type==='Lỗi tài liệu số':session.role==='warehouse'?c.type==='Sự cố vật lý':true)}
function casesView(){return shell('Sự cố và đề xuất','Ghi nhận bằng chứng, xử lý và chuyển phê duyệt khi cần.',`<div class="toolbar"><span>Hồ sơ theo trách nhiệm</span>${btn('Lập hồ sơ','staffCase()',true)}</div><section class="panel">${table(['Hồ sơ','Loại','Trạng thái',''],relevantCases().map(c=>[esc(c.title),esc(c.type),badge(c.status,'blue'),btn('Xử lý hồ sơ',`caseEdit(${c.id})`)]))}</section>`)}
function staffCase(){formDialog('Lập hồ sơ sự cố',inputField('title','Tiêu đề')+inputField('detail','Hiện trạng / bằng chứng','','textarea'),v=>{db.cases.push({id:db.cases.length+1,...v,type:session.role==='digital'?'Lỗi tài liệu số':'Sự cố vật lý',status:'Mới tiếp nhận'});log('Lập hồ sơ sự cố')})}
function caseEdit(id){let c=db.cases.find(x=>x.id===id);formDialog('Xử lý: '+esc(c.title),inputField('detail','Ghi nhận / bằng chứng',c.detail,'textarea')+inputField('status','Bước xử lý',c.status,'text',['Đang xử lý','Cần bổ sung','Chờ quản lý duyệt','Đã giải quyết']),v=>{Object.assign(c,v);if(c.requestId){let r=db.requests.find(x=>x.id===c.requestId);r.status=v.status;r.feedback=v.detail}if(v.status==='Chờ quản lý duyệt')addApproval('Phương án sự cố',c.title,c);log('Cập nhật hồ sơ sự cố '+id)})}
function paymentsView(){return shell('Khoản phạt và thu tiền','Ghi nhận khoản thực thu; tính phạt không đồng nghĩa đã thanh toán.',`<section class="panel">${table(['Nội dung','Phải thu','Đã thu','Được miễn','Còn lại',''],db.fees.map(f=>[esc(f.title),money(f.amount),money(f.paid),money(f.waived),money(amountLeft(f)),amountLeft(f)>0?btn('Ghi nhận thu',`collectFee(${f.id})`):badge('Đã hoàn tất')]))}</section><section class="panel"><h2>Lịch sử thu</h2>${table(['Mã biên nhận','Số tiền','Người thu',''],db.receipts.map(r=>[r.code,money(r.amount),r.by,btn('Tải biên nhận',`downloadText('${r.code}.txt','Biên nhận minh họa ${r.code} - ${r.amount} VND')`)]))}</section>`)}
function collectFee(id){let f=db.fees.find(x=>x.id===id);formDialog('Ghi nhận thu tại quầy',inputField('amount','Số tiền đã nhận',amountLeft(f),'number'),v=>{let a=Number(v.amount);if(a<=0||a>amountLeft(f))throw Error('Số tiền phải lớn hơn 0 và không vượt số còn phải thu.');f.paid+=a;db.receipts.push({code:'PT-'+(db.receipts.length+1).toString().padStart(4,'0'),amount:a,by:roles[session.role]});log('Ghi nhận thu '+money(a))},'Xác nhận đã nhận tiền','Chỉ mô phỏng ghi sổ; không thực hiện giao dịch tài chính thật.')}
function filterRows(el){let scope=el.closest('.panel');scope.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!norm(tr.textContent).includes(norm(el.value)))}
function catalogView(){return shell('Danh mục tài liệu','Biên mục bản ghi và theo dõi quá trình xét duyệt.',`<div class="toolbar"><span>${books.length} bản ghi</span>${btn('Tạo bản ghi',"db.editId=null;go('editor')",true)}</div><section class="panel"><div class="toolbar"><input aria-label="Tìm bản ghi" placeholder="Tên tài liệu, tác giả hoặc mã" oninput="filterRows(this)"></div>${table(['Mã','Nhan đề','Loại','Trạng thái',''],books.map(b=>[b.code,`<strong>${esc(b.title)}</strong><small>${esc(b.author)}</small>`,b.type,badge(b.status,'blue'),btn('Biên tập',`db.editId=${b.id};go('editor')`)]))}</section>`)}
function editorView(){let b=books.find(x=>x.id===db.editId)||{};return shell(b.id?'Biên tập bản ghi':'Tạo bản ghi tài liệu','Metadata, phân loại và lưu nháp trong cùng một biểu mẫu.',`<div class="formlayout"><form class="panel" onsubmit="event.preventDefault();saveRecord(this,event.submitter.value)"><div class="formgrid">${inputField('title','Nhan đề *',b.title)}${inputField('author','Tác giả *',b.author)}${inputField('year','Năm xuất bản',b.year||2026,'number')}${inputField('isbn','ISBN (nếu có)',b.isbn||'').replace(' required','')}${inputField('subject','Chủ đề',b.subject||'Công nghệ thông tin','text',['Công nghệ thông tin','Thiết kế','Kinh tế','Khoa học cơ bản'])}${inputField('type','Loại tài liệu',b.type||'Sách in','text',['Sách in','Tài liệu số','Luận văn'])}<div class="full">${inputField('desc','Tóm tắt',b.desc||'','textarea')}</div></div><div class="actions"><button type="button" onclick="go('inventory')">Quay lại</button><button value="draft">Lưu nháp</button><button class="primary" value="review">Gửi xét duyệt</button></div></form><aside class="panel"><h3>Kiểm tra trước khi gửi</h3><p class="muted">Kiểm tra nhan đề, tác giả, chủ đề và nguồn mô tả. ISBN được kiểm tra nếu có nhập.</p>${badge(b.status||'Bản ghi mới','blue')}<div class="note">AI chỉ tạo gợi ý. Cán bộ kiểm tra trước khi gửi duyệt.</div>${btn('Nhập từ ISBN / tệp',"go('ai')")}</aside></div>`)}
function saveRecord(form,mode){let v=Object.fromEntries(new FormData(form));if(v.isbn&&!/^(\d{10}|\d{13})$/.test(v.isbn.replace(/[- ]/g,'')))return toast('ISBN cần 10 hoặc 13 chữ số; đây là kiểm tra định dạng mẫu.');let b=books.find(x=>x.id===db.editId);if(!b){b={id:Math.max(...books.map(x=>x.id))+1,copies:0,shelf:'Chưa xếp kệ',color:'#345d7b',code:'BG-'+(books.length+1),cover:'Bản ghi<br>mới'};books.push(b)}Object.assign(b,v,{year:Number(v.year),status:mode==='review'?'Chờ duyệt':'Bản nháp'});db.editId=b.id;if(mode==='review')addApproval('Bản ghi',b.title,b);log('Lưu bản ghi '+b.code);go('inventory');toast(mode==='review'?'Đã gửi xét duyệt.':'Đã lưu nháp.')}
function aiView(){return shell('Hỗ trợ biên mục tự động','Thử cách nhập nguồn và rà soát gợi ý; chưa kết nối AI hoặc dịch vụ ISBN.',`<div class="split"><form class="panel" onsubmit="event.preventDefault();aiDraft(this)"><h2>Nguồn biên mục</h2>${inputField('isbn','ISBN mẫu','9786040000000')}<p class="muted" style="margin-top:15px">Hoặc chọn ảnh/PDF để minh họa vị trí nhập tệp.</p><input aria-label="Chọn tệp để biên mục" type="file" accept="image/*,.pdf"><div class="actions"><button class="primary">Tạo gợi ý mẫu</button></div></form><section class="panel"><h2>Cán bộ giữ quyền quyết định</h2><p>Rà soát thông tin, sửa từng trường và loại bỏ dữ liệu chưa chắc chắn. Kết quả được lưu dưới dạng nháp.</p><div class="note">Kết quả thử được tạo cố định, không phải nội dung trích xuất từ tệp.</div></section></div>`)}
function aiDraft(form){let id=Math.max(...books.map(x=>x.id))+1;books.push({id,title:'Bản nháp minh họa từ nguồn nhập',author:'Cần xác minh tác giả',isbn:form.elements.isbn.value,year:2026,subject:'Công nghệ thông tin',type:'Sách in',copies:0,shelf:'Chưa xếp kệ',code:'BG-'+id,color:'#345d7b',cover:'Bản nháp<br>cần rà soát',desc:'Gợi ý cố định để thử giao diện. Cán bộ cần thay bằng dữ liệu đã kiểm chứng.',status:'Bản nháp'});db.editId=id;log('Tạo bản nháp mẫu');go('editor')}
function copiesView(){return shell('Bản sao và vị trí','Mỗi mã cuốn đại diện một bản vật lý.',`<div class="toolbar"><span>${db.copies.length} bản sao mẫu</span>${btn('Đăng ký bản sao','newCopy()',true)}</div><section class="panel">${table(['Mã cuốn','Tài liệu','Vị trí','Trạng thái',''],db.copies.map(c=>[esc(c.code),esc(book(c.book).title),esc(c.location),badge(c.status,c.status==='Sẵn sàng'?'':'warn'),btn('Điều chuyển',`moveCopy(${c.id})`)+btn('In tem',`printTag(${c.id})`)+btn('Ngừng phục vụ',`withdrawCopy(${c.id})`)]))}</section>`)}
function newCopy(){formDialog('Đăng ký bản sao',inputField('book','Tài liệu',books[0].title,'text',books.filter(b=>b.type==='Sách in').map(b=>b.title))+inputField('code','Mã cuốn')+inputField('location','Vị trí kệ'),v=>{if(db.copies.some(c=>c.code===v.code))throw Error('Mã cuốn đã tồn tại.');let b=books.find(x=>x.title===v.book);db.copies.push({id:db.copies.length+1,...v,book:b.id,status:'Sẵn sàng'});b.copies++;log('Đăng ký bản sao '+v.code)})}
function moveCopy(id){let c=db.copies.find(x=>x.id===id);if(c.status==='Đang mượn')return toast('Bản sao đang mượn, chưa thể điều chuyển.');formDialog('Điều chuyển '+esc(c.code),inputField('location','Vị trí mới',c.location)+inputField('reason','Lý do'),v=>{c.location=v.location;log('Điều chuyển '+c.code+' đến '+v.location+': '+v.reason)})}
function printTag(id){let c=db.copies.find(x=>x.id===id);downloadText('tem-'+c.code+'.txt','THẺ NHẬN DIỆN MINH HỌA\n'+c.code+'\n'+book(c.book).title+'\n'+c.location)}
function withdrawCopy(id){let c=db.copies.find(x=>x.id===id);if(c.status==='Đang mượn')return toast('Chưa thể ngừng phục vụ khi sách đang mượn.');if(c.status==='Ngừng phục vụ')return toast('Bản sao đã ngừng phục vụ.');formDialog('Ngừng phục vụ bản sao',inputField('reason','Lý do'),v=>{c.status='Ngừng phục vụ';book(c.book).copies=Math.max(0,book(c.book).copies-1);log('Ngừng phục vụ '+c.code+': '+v.reason)})}
function stockView(){let s=db.stocks.find(x=>x.id===db.stockId)||db.stocks[0];return shell('Kiểm kê','Quét mã và tra soát sai lệch trước khi kết luận thất lạc.',`<div class="toolbar"><select aria-label="Chọn đợt kiểm kê" onchange="db.stockId=Number(this.value);render()">${db.stocks.map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>${btn('Tạo đợt','newStock()',true)}</div><section class="panel"><div class="row"><h2>${esc(s.title)}</h2>${badge(s.status,'blue')}</div><p class="muted">Phạm vi: ${esc(s.area)} · Đã quét ${s.seen.length} mã</p><form class="scan" onsubmit="event.preventDefault();stockScan(this.elements.code.value)"><input name="code" required aria-label="Mã cuốn kiểm kê" placeholder="Ví dụ AI-001-001"><button ${s.status==='Đã kết thúc'?'disabled':''}>Ghi nhận quét</button></form>${table(['Bản sao','Vị trí','Kết quả'],db.copies.filter(c=>s.area==='Toàn bộ'||c.location.startsWith(s.area==='Tầng 2'?'T2':'T3')).map(c=>[c.code,c.location,badge(s.seen.includes(c.code)?'Đã thấy':c.status==='Đang mượn'?'Vắng mặt hợp lệ':'Chưa quét',s.seen.includes(c.code)?'':'warn')]))}<div class="actions">${btn('Lập hồ sơ tra soát','stockInvestigate()')}${s.status!=='Đã kết thúc'?btn('Kết thúc đợt',`change(db.stocks.find(x=>x.id===db.stockId),'status','Đã kết thúc','Kết thúc đợt kiểm kê')`,true):''}</div></section>`)}
function newStock(){formDialog('Tạo đợt kiểm kê',inputField('title','Tên đợt')+inputField('area','Khu vực','Tầng 2','text',['Tầng 2','Tầng 3','Toàn bộ']),v=>{let s={id:db.stocks.length+1,...v,status:'Đang thực hiện',seen:[]};db.stocks.push(s);db.stockId=s.id;log('Tạo đợt '+v.title)})}
function stockScan(code){let s=db.stocks.find(x=>x.id===db.stockId);let c=db.copies.find(x=>x.code===code.trim());if(!c)return toast('Mã cuốn không tồn tại.');if(s.seen.includes(c.code))return toast('Mã này đã được quét.');s.seen.push(c.code);log('Kiểm kê thấy '+c.code);render()}
function stockInvestigate(){let s=db.stocks.find(x=>x.id===db.stockId);db.cases.push({id:db.cases.length+1,title:'Tra soát: '+s.title,type:'Sự cố vật lý',status:'Đang xử lý',detail:'Đối chiếu bản chưa quét với khoản mượn, điều chuyển và vị trí thực tế.'});log('Lập hồ sơ tra soát kiểm kê');toast('Đã tạo hồ sơ tại Sự cố & đề xuất.')}
function intakeView(){return shell('Tiếp nhận công trình','Kiểm tra hồ sơ và phản hồi người nộp.',`<section class="panel">${table(['Công trình','Loại','Trạng thái',''],state.submissions.map(s=>[esc(s.title),esc(s.type),badge(s.status,'blue'),btn('Kiểm tra hồ sơ',`intakeEdit(${s.id})`)]))}</section>`)}
function intakeEdit(id){let s=state.submissions.find(x=>x.id===id);formDialog('Kiểm tra hồ sơ',inputField('feedback','Kết quả kiểm tra / hướng dẫn bổ sung',s.feedback||'Đã kiểm tra thông tin hồ sơ.','textarea')+inputField('status','Kết quả',s.status,'text',['Cần bổ sung','Đã tiếp nhận','Từ chối'])+inputField('print','Bản in','Không yêu cầu','text',['Không yêu cầu','Đã nhận','Chưa nhận']),v=>{if(v.status==='Đã tiếp nhận'&&v.print==='Chưa nhận')throw Error('Chưa nhận bản in bắt buộc; cần bổ sung trước khi tiếp nhận.');Object.assign(s,v);if(v.status==='Đã tiếp nhận'&&!db.resources.some(r=>r.submissionId===id))db.resources.push({id:db.resources.length+1,title:s.title,kind:'Tệp PDF',access:s.access,status:'Chưa công bố',version:1,submissionId:id});log('Tiếp nhận hồ sơ '+id+': '+v.status)},'Lưu kết quả',s.title+' · '+s.filename)}
function resourcesView(){return shell('Quản lý tài nguyên số','Phiên bản tệp, liên kết, giấy phép và phạm vi công bố.',`<div class="toolbar"><span>${db.resources.length} tài nguyên</span>${btn('Thêm tài nguyên','resourceEdit()',true)}</div><section class="panel">${table(['Tài nguyên','Loại / phiên bản','Truy cập','Trạng thái',''],db.resources.map(r=>[esc(r.title),r.kind+' · v'+r.version,esc(r.access),badge(r.status,'blue'),btn('Chỉnh sửa',`resourceEdit(${r.id})`)+btn('Đề xuất công bố',`publishRequest(${r.id})`)]))}</section>`)}
function resourceEdit(id){let r=db.resources.find(x=>x.id===id)||{};formDialog(id?'Chỉnh sửa tài nguyên':'Thêm tài nguyên',inputField('title','Nhan đề',r.title)+inputField('kind','Loại',r.kind||'Tệp PDF','text',['Tệp PDF','Liên kết ngoài'])+inputField('url','Tên tệp / URL',r.url||'tai-lieu.pdf')+inputField('access','Phạm vi',r.access||'Thành viên trường','text',['Thành viên trường','Công khai','Trong khuôn viên','Hạn chế'])+inputField('license','Căn cứ bản quyền / giấy phép',r.license||'Cần xác minh')+inputField('release','Ngày đề xuất công bố',r.release||'2026-11-01','date'),v=>{if(v.kind==='Liên kết ngoài'&&!/^https:\/\//.test(v.url))throw Error('Liên kết ngoài cần bắt đầu bằng https://');if(id){Object.assign(r,v);r.version++;r.status='Chưa công bố'}else db.resources.push({id:db.resources.length+1,...v,version:1,status:'Chưa công bố'});log('Lưu tài nguyên số '+v.title)})}
function publishRequest(id){let r=db.resources.find(x=>x.id===id);if(!r.license||r.license==='Cần xác minh')return toast('Bổ sung căn cứ bản quyền trước khi trình công bố.');addApproval('Công bố số',r.title,r);r.status='Chờ duyệt';render()}
function approvalsView(){return shell('Hàng chờ phê duyệt','Mỗi loại hồ sơ có nội dung quyết định riêng.',`<section class="panel"><div class="toolbar"><input aria-label="Lọc hồ sơ phê duyệt" placeholder="Tìm theo tên, loại hoặc trạng thái" oninput="filterRows(this)"></div>${table(['Hồ sơ','Loại','Trạng thái',''],db.approvals.map(a=>[esc(a.title),a.kind,badge(a.status,'blue'),a.status==='Chờ duyệt'?btn('Xem và quyết định',`decide(${a.id})`):esc(a.reason||'')]))}</section>`)}
function decide(id){let a=db.approvals.find(x=>x.id===id);let fields=inputField('decision','Quyết định','Chấp thuận','text',['Chấp thuận','Yêu cầu chỉnh sửa','Từ chối'])+inputField('reason','Nhận xét / lý do','','textarea');if(a.kind==='Miễn giảm phạt')fields+=inputField('amount','Số tiền miễn giảm',amountLeft(db.fees.find(f=>f.id===a.data.fee)),'number');if(a.kind==='Công bố số')fields+=`<div class="note">Phạm vi: ${esc(a.data.access)}<br>Giấy phép: ${esc(a.data.license)}<br>Ngày đề xuất: ${esc(a.data.release||'Chưa đặt')}</div>`;formDialog('Quyết định: '+esc(a.title),fields,v=>{if(a.kind==='Miễn giảm phạt'&&v.decision==='Chấp thuận'){let f=db.fees.find(x=>x.id===a.data.fee),n=Number(v.amount);if(n<0||n>amountLeft(f))throw Error('Số miễn giảm không được vượt số còn phải thu.');f.waived+=n}a.status=v.decision;a.reason=v.reason;if(a.kind==='Bản ghi')a.data.status=v.decision==='Chấp thuận'?'Đã duyệt':v.decision;if(a.kind==='Công bố số'){a.data.status=v.decision==='Chấp thuận'?'Đã công bố':v.decision;let s=state.submissions.find(x=>x.id===a.data.submissionId);if(s&&v.decision==='Chấp thuận')s.status='Đã công bố'}if(a.kind==='Phương án sự cố')a.data.status=v.decision==='Chấp thuận'?'Đã duyệt phương án':v.decision;log(v.decision+': '+a.title)},'Lưu quyết định')}
function reportsView(){return shell('Báo cáo hoạt động','Báo cáo dựa trên dữ liệu của phiên mô phỏng.',`<div class="tiles"><div class="tile">Khoản mượn đang mở<strong>${state.loans.length}</strong></div><div class="tile">Đã nhận trả<strong>${state.history.length}</strong></div><div class="tile">Đã thu phạt<strong>${money(db.fees.reduce((s,f)=>s+f.paid,0))}</strong></div></div><section class="panel"><div class="row"><h2>Hiện trạng tài liệu</h2>${btn('Xuất CSV','exportReport()',true)}</div>${books.map(b=>`<div class="statbar"><span>${b.code}</span><i style="width:${Math.max(2,b.copies*35)}px"></i><small>${b.copies} bản sẵn sàng</small></div>`).join('')}</section><section class="panel"><h2>Hồ sơ xử lý</h2>${table(['Nhóm','Số lượng'],[['Yêu cầu bạn đọc',db.requests.length],['Sự cố',db.cases.length],['Công trình đã nộp',state.submissions.length],['Hồ sơ chờ duyệt',db.approvals.filter(a=>a.status==='Chờ duyệt').length]])}</section>`)}
function exportReport(){downloadText('bao-cao.csv','\uFEFFMa,Nhan de,Ban san sang\n'+books.map(b=>[b.code,'"'+b.title.replace(/"/g,'""')+'"',b.copies].join(',')).join('\n'))}
function policyView(){return shell('Chính sách mượn','Mỗi thay đổi tạo phiên bản, giữ lịch sử chính sách trước đó.',`<div class="toolbar"><span>Chính sách mẫu phục vụ thiết kế</span>${btn('Tạo phiên bản','newPolicy()',true)}</div><section class="panel">${table(['Chính sách','Hạn mức','Thời hạn','Gia hạn','Hiệu lực','Trạng thái'],db.policies.map(p=>[esc(p.name),p.limit+' cuốn',p.days+' ngày',p.renew+' lần / '+p.extra+' ngày',p.effective,badge(p.status,'blue')]))}</section><div class="note">Các thông số này được lưu để xem thiết kế; chưa kết nối bộ tính hạn và điều kiện giao dịch.</div>`)}
function newPolicy(){formDialog('Phiên bản chính sách mới',inputField('name','Tên chính sách')+inputField('limit','Hạn mức cuốn',5,'number')+inputField('days','Thời hạn mượn (ngày)',30,'number')+inputField('renew','Số lần gia hạn',1,'number')+inputField('extra','Số ngày mỗi lần gia hạn',7,'number')+inputField('fee','Phạt mỗi ngày',5000,'number')+inputField('effective','Ngày hiệu lực','2026-11-01','date'),v=>{db.policies.push({id:db.policies.length+1,...v,status:'Chờ hiệu lực'});log('Tạo phiên bản chính sách '+v.name)},'Lưu phiên bản')}
function accountsView(){return shell('Tài khoản và vai trò','Admin quản lý quyền; không mặc nhiên có quyền phê duyệt nghiệp vụ.',`<div class="toolbar"><span>${db.accounts.length} tài khoản mẫu</span>${btn('Tạo tài khoản','accountEdit()',true)}</div><section class="panel">${table(['Người dùng','Email','Vai trò','Trạng thái',''],db.accounts.map(a=>[esc(a.name),esc(a.email),roles[a.role],badge(a.status,a.status==='Hoạt động'?'':'warn'),btn('Phân quyền',`accountEdit(${a.id})`)+btn(a.status==='Hoạt động'?'Khóa':'Mở khóa',`accountToggle(${a.id})`)]))}</section>`)}
function accountEdit(id){let a=db.accounts.find(x=>x.id===id)||{};formDialog(id?'Chỉnh sửa tài khoản':'Tạo tài khoản mẫu',inputField('name','Họ tên',a.name)+inputField('email','Email',a.email,'email')+inputField('role','Vai trò',roles[a.role]||roles.reader,'text',Object.values(roles)),v=>{let r=Object.keys(roles).find(k=>roles[k]===v.role);if(db.accounts.some(x=>x.email===v.email&&x.id!==id))throw Error('Email đã tồn tại.');if(id)Object.assign(a,v,{role:r});else db.accounts.push({id:db.accounts.length+1,...v,role:r,status:'Hoạt động',mustChangePassword:true});log('Cập nhật quyền tài khoản '+v.email)})}
function accountToggle(id){let a=db.accounts.find(x=>x.id===id);formDialog(a.status==='Hoạt động'?'Khóa tài khoản':'Mở khóa tài khoản',inputField('reason','Lý do'),v=>{a.status=a.status==='Hoạt động'?'Bị khóa':'Hoạt động';log(a.status+': '+a.email+' — '+v.reason)})}
function settingsView(){return shell('Cấu hình hệ thống','Điểm phục vụ và tham số vận hành mẫu.',`<form class="panel" onsubmit="event.preventDefault();Object.assign(db.settings,Object.fromEntries(new FormData(this)));log('Lưu cấu hình hệ thống');toast('Đã lưu cấu hình mẫu.');"><div class="formgrid">${inputField('branch','Tên điểm phục vụ',db.settings.branch)}${inputField('email','Email thư viện',db.settings.email,'email')}${inputField('hold','Số ngày giữ sách',db.settings.hold,'number')}${inputField('closed','Ngày đóng cửa',db.settings.closed,'text',['Chủ nhật','Thứ bảy và Chủ nhật','Không có'])}</div><div class="actions"><button class="primary">Lưu cấu hình</button></div></form><div class="note">Thiết lập được lưu trong phiên xem, chưa điều khiển email hay tác vụ nền.</div>`)}
function auditView(){return shell('Nhật ký thao tác','Lịch sử chỉ đọc của phiên thiết kế.',`<section class="panel"><div class="toolbar"><input aria-label="Lọc nhật ký" placeholder="Tìm thao tác hoặc vai trò" oninput="filterRows(this)">${btn('Xuất nhật ký',"downloadText('nhat-ky.txt',db.audit.map(x=>x.time+' | '+x.role+' | '+x.action).join('\\n'))")}</div>${table(['Thời điểm','Vai trò','Thao tác'],db.audit.map(a=>[a.time,esc(a.role),esc(a.action)]))}</section>`)}
function notificationsView(){let items=session.role==='reader'?[...state.submissions.map(s=>'Hồ sơ “'+s.title+'”: '+s.status),...state.holds.map(h=>'Đặt trước “'+book(h.id).title+'”: '+(h.status||'Chờ sách'))]:db.audit.slice(0,10).map(a=>a.action);return shell('Thông báo','Các thay đổi gần đây trong dữ liệu mẫu.',`<section class="panel">${items.length?items.map(x=>`<p style="padding:14px 0;border-bottom:1px solid var(--line)">${esc(x)}</p>`).join(''):'<p class="muted">Chưa có thông báo mới.</p>'}</section>`)}
function downloadText(name,text){let u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Đã tải '+name)}
// Gate actions exposed on the public catalog; real security requires server-side enforcement.
const originalHold=hold;hold=function(id){if(session.role!=='reader')return go('login');if(db.card.status!=='Hoạt động')return toast('Thẻ bị khóa, chưa thể đặt trước.');if(state.holds.some(h=>h.id===id))return toast('Bạn đã đặt trước tài liệu này.');originalHold(id)};
commitDesk=function(){if(session.role!=='circulation')return toast('Chức năng dành cho cán bộ mượn trả.');if(state.deskTab==='out'&&(db.card.status!=='Hoạt động'||state.loans.length+state.scanned.length>5))return toast('Kiểm tra lại hiệu lực thẻ và hạn mức.');old.commitDesk();log('Hoàn tất giao dịch tại quầy')};
const baseRenew=renew;renew=function(id){if(!['reader','circulation'].includes(session.role))return go('login');if(db.card.status!=='Hoạt động')return toast('Thẻ bị khóa, chưa thể gia hạn.');baseRenew(id)};
const baseRead=reader;views.reader=()=>{if(!session.role)return `<div class="wrap"><div class="panel"><h2>Tài liệu dành cho thành viên</h2><p>Đăng nhập bằng vai trò bạn đọc để xem bản minh họa.</p>${btn('Đăng nhập',"go('login')",true)}</div></div>`;return old.reader()};
const baseDownload=downloadSample;downloadSample=function(){if(!session.role)return go('login');baseDownload()};
// New submissions retain unique identifiers across seeded and user-created records.
nextStep=function(){if(session.role!=='reader')return go('login');old.nextStep();};
// Complete the final publication step independently of the review decision.
const pendingView=approvalsView;
views.approvals=function(){return pendingView()+`<div class="wrap"><section class="panel"><h2>Bản ghi đã duyệt / đang công bố</h2>${table(['Bản ghi','Trạng thái','Thao tác'],books.filter(b=>['Đã duyệt','Đã công bố'].includes(b.status)).map(b=>[esc(b.title),badge(b.status,'blue'),btn(b.status==='Đã duyệt'?'Công bố bản ghi':'Ngừng công bố',`publishCatalog(${b.id})`)]))}</section></div>`};
function publishCatalog(id){if(session.role!=='manager')return toast('Cần quyền quản lý nghiệp vụ.');let b=book(id);formDialog(b.status==='Đã duyệt'?'Công bố bản ghi':'Ngừng công bố bản ghi',inputField('reason','Lý do / ghi chú'),v=>{b.status=b.status==='Đã duyệt'?'Đã công bố':'Ngừng công bố';log(b.status+': '+b.title+' — '+v.reason)})}
// Give ManagerLib an inspectable initial queue without needing to create records first.
let draftId=Math.max(...books.map(b=>b.id))+1;
let draft={id:draftId,title:'Cơ sở dữ liệu trong hệ thống thông tin',author:'Lê Hoàng Phương',year:2026,subject:'Công nghệ thông tin',type:'Sách in',copies:0,shelf:'Chưa xếp kệ',code:'BG-007',color:'#345d7b',cover:'Cơ sở<br>dữ liệu',desc:'Bản ghi mẫu để trải nghiệm luồng xét duyệt và công bố.',status:'Chờ duyệt'};
books.push(draft);db.approvals.push({id:1,kind:'Bản ghi',title:draft.title,data:draft,status:'Chờ duyệt'});
const beforeDetail=views.detail;
views.detail=function(){let b=book(state.selected);if(b.status!=='Đã công bố'&&(!session.role||session.role==='reader'))return `<div class="wrap"><section class="panel"><h2>Tài liệu chưa được công bố</h2>${btn('Quay lại tra cứu',"go('search')")}</section></div>`;return beforeDetail()};
// Conditions are illustrative; no backend authorization or identity provider is connected.
session.role=null;state.page='login';state.staff=false;render();
